const seen = $getWorkflowStaticData('global').seenIds ?? [];
const ghRaw = $('Fetch GitHub Advisories').all().map(i => i.json);
const advisories = ghRaw;
const nvdRaw = $('Fetch NVD CVEs').first()?.json?.vulnerabilities ?? [];
const releaseEntries = $('Parse Releases XML').first()?.json?.feed?.entry ?? [];
const releases = Array.isArray(releaseEntries) ? releaseEntries : [releaseEntries];
const jpcertRaw = $('Parse JPCERT XML').first()?.json?.['rdf:RDF']?.item ?? [];
const jpcertItems = Array.isArray(jpcertRaw) ? jpcertRaw : [jpcertRaw];
const jvnRaw = $('Parse JVN XML').first()?.json?.['rdf:RDF']?.item ?? [];
const jvnItems = Array.isArray(jvnRaw) ? jvnRaw : [jvnRaw];

const normalizeGH = (items) => items
  .filter(item => {
    const pkgNames = (item.vulnerabilities ?? [])
      .map(v => (v.package?.name ?? '').toLowerCase());
    return pkgNames.some(name => name === 'n8n');
  })
  .map(item => ({
    id:        item.ghsa_id,
    title:     item.summary,
    severity:  (item.severity ?? 'UNKNOWN').toUpperCase(),
    url:       item.html_url,
    published: item.published_at,
  })).filter(i => i.id);

const normalizeNVD = (items) => items.map(item => ({
  id:        item.cve?.id,
  title:     item.cve?.descriptions?.find(d => d.lang === 'en')?.value ?? '',
  severity:  item.cve?.metrics?.cvssMetricV31?.[0]?.cvssData?.baseSeverity ?? 'UNKNOWN',
  url:       `https://nvd.nist.gov/vuln/detail/${item.cve?.id}`,
  published: item.cve?.published,
})).filter(i => i.id);

const normalizeReleases = (items) => items
  .filter(i => /security/i.test(i.title?.[0] ?? ''))
  .map(item => ({
    id:        item.id?.[0],
    title:     item.title?.[0],
    severity:  'INFO',
    url:       item.link?.[0]?.$.href ?? '',
    published: item.updated?.[0],
  })).filter(i => i.id);

const normalizeJPCERT = (items) => items.map(item => ({
  id:        item['rdf:about'],
  title:     item.title,
  severity:  'INFO',
  url:       item.link,
  published: item['dc:date'],
})).filter(i => i.id);

const normalizeJVN = (items) => items.map(item => ({
  id:        item['rdf:about'],
  title:     item.title,
  severity:  'INFO',
  url:       item.link,
  published: item['dc:date'],
})).filter(i => i.id);

const all = [
  ...normalizeGH(advisories),
  ...normalizeNVD(nvdRaw),
  ...normalizeReleases(releases),
  ...normalizeJPCERT(jpcertItems),
  ...normalizeJVN(jvnItems),
];

const newItems = all.filter(i => !seen.includes(i.id));
return [{ json: { newItems, count: newItems.length } }];

const summaryText = $json.content?.[0]?.text ?? $json.text ?? 'Failed to generate summary';

const blocksArray = [
  {
    type: "header",
    text: { type: "plain_text", text: "🚨 New security advisories", emoji: true }
  },
  {
    type: "section",
    text: {
      type: "mrkdwn",
      text: summaryText.length > 2900 ? summaryText.slice(0, 2900) + '\n...(省略)' : summaryText
    }
  },
  {
    type: "context",
    elements: [{ type: "mrkdwn", text: `Auto-detected by n8n | ${new Date().toISOString()}` }]
  }
];

return [{ json: {
  blocksString: JSON.stringify({ blocks: blocksArray }),
  notification: `New security advisories detected`
} }];

const seen   = $getWorkflowStaticData('global').seenIds ?? [];
const newIds = $('Filter New Advisories').all()
                 .flatMap(i => i.json.newItems.map(n => n.id));
const updated = [...new Set([...seen, ...newIds])].slice(-500);
$getWorkflowStaticData('global').seenIds = updated;
return [{ json: { saved: newIds.length, totalTracked: updated.length } }];
